import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class LittleElephantAndBallot {
    static final int MOD = 1_000_000_007;
    static final int MAX_LUCKY = 10;
    static final int NUM_OTHERS = 6;
    static final int MAX_SUM = NUM_OTHERS * MAX_LUCKY;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long m = Long.parseLong(br.readLine());

        // Count numbers from 1 to m by their lucky digit count
        long[] totalCount = new long[MAX_LUCKY + 1];
        long[] digits = getDigits(m);
        long[][][] memo = new long[digits.length + 1][MAX_LUCKY + 1][2];
        for (long[][] arr2d : memo) {
            for (long[] arr1d : arr2d) {
                Arrays.fill(arr1d, -1);
            }
        }
        long[] count1toM = dp(digits, 0, 0, 1, memo);
        System.arraycopy(count1toM, 0, totalCount, 0, MAX_LUCKY + 1);

        // Precompute combinations
        long[][] C = new long[m + 1 < 100 ? (int)m + 1 : 100][7];
        for (int i = 0; i < C.length; i++) {
            C[i][0] = 1;
            for (int j = 1; j < 7 && j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }

        long ans = 0;
        for (int L = 1; L <= MAX_LUCKY; L++) {
            if (totalCount[L] == 0) continue;
            // Count ways to choose 6 numbers for other parties
            // such that sum of their lucky digits < L
            // Use DP: dp[i][j] = ways to choose i numbers with total lucky sum j
            long[][] dpOthers = new long[NUM_OTHERS + 1][MAX_SUM + 1];
            dpOthers[0][0] = 1;
            for (int k = 0; k <= MAX_LUCKY; k++) {
                long avail = totalCount[k];
                if (k == L) avail--; // one taken by Little Elephant
                if (avail < 0) continue;
                // We need to choose cnt numbers from this group (0 to 6)
                // ways to choose cnt from avail = C(avail, cnt)
                // Update DP backwards
                for (int i = NUM_OTHERS; i >= 0; i--) {
                    for (int s = 0; s <= MAX_SUM; s++) {
                        if (dpOthers[i][s] == 0) continue;
                        for (int cnt = 1; cnt <= 6 - i && cnt <= avail; cnt++) {
                            int newI = i + cnt;
                            int newS = s + cnt * k;
                            if (newS > MAX_SUM) continue;
                            long ways = nCrMod(avail, cnt);
                            dpOthers[newI][newS] = (dpOthers[newI][newS] + dpOthers[i][s] * ways) % MOD;
                        }
                    }
                }
            }
            long waysOthers = 0;
            for (int s = 0; s < L; s++) {
                waysOthers = (waysOthers + dpOthers[NUM_OTHERS][s]) % MOD;
            }
            ans = (ans + totalCount[L] % MOD * waysOthers) % MOD;
        }

        // Multiply by 6! = 720 for permutations of other parties
        ans = ans * 720 % MOD;
        System.out.println(ans);
    }

    static long[] getDigits(long x) {
        String s = Long.toString(x);
        long[] d = new long[s.length()];
        for (int i = 0; i < s.length(); i++) {
            d[i] = s.charAt(i) - '0';
        }
        return d;
    }

    static long[] dp(long[] digits, int pos, int cnt, int tight, long[][][] memo) {
        if (pos == digits.length) {
            long[] res = new long[MAX_LUCKY + 1];
            if (cnt <= MAX_LUCKY) res[cnt] = 1;
            return res;
        }
        if (memo[pos][cnt][tight] != -1 && tight == 0) {
            // We need to return an array, but memo stores a single value? 
            // This approach is flawed. Let's use a Map for memoization keyed by (pos, cnt, tight) returning array.
            // Actually, standard digit DP returns a single number. Here we need distribution of counts.
            // Better to do DP returning array, memoize with Map.
        }
        // Let's reimplement digit DP with Map memoization.
        return null;
    }

    // Replacing the digit DP with a cleaner implementation using Map
    static Map<Long, long[]> memoMap = new HashMap<>();

    static long[] solveDigitDP(long[] digits) {
        memoMap.clear();
        return digitDP(digits, 0, 0, true);
    }

    static long[] digitDP(long[] digits, int pos, int cnt, boolean tight) {
        if (pos == digits.length) {
            long[] res = new long[MAX_LUCKY + 1];
            if (cnt <= MAX_LUCKY) res[cnt] = 1;
            return res;
        }
        long key = ((long)pos << 32) | ((long)cnt << 1) | (tight ? 1 : 0);
        if (memoMap.containsKey(key)) return memoMap.get(key);

        long[] res = new long[MAX_LUCKY + 1];
        int limit = tight ? (int)digits[pos] : 9;
        for (int d = 0; d <= limit; d++) {
            boolean nextTight = tight && (d == limit);
            int nextCnt = cnt + ((d == 4 || d == 7) ? 1 : 0);
            if (nextCnt > MAX_LUCKY) continue; // optimization
            long[] sub = digitDP(digits, pos + 1, nextCnt, nextTight);
            for (int i = 0; i <= MAX_LUCKY; i++) {
                res[i] = (res[i] + sub[i]) % MOD;
            }
        }
        memoMap.put(key, res);
        return res;
    }

    static long nCrMod(long n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        long num = 1;
        for (int i = 0; i < k; i++) {
            num = num * ((n - i) % MOD) % MOD;
        }
        long den = 1;
        for (int i = 1; i <= k; i++) {
            den = den * i % MOD;
        }
        return num * modInverse(den) % MOD;
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long modInverse(long a) {
        return modPow(a, MOD - 2);
    }
}
